∀ {ι : Type u_1} {D : Type} {d h : ℝ} {vr vt : NavierStokes.TorusInverse.Plane}
  {sys : NavierStokes.PartitionedCovariance.SlotSystem d h vr vt} {label : ℕ → ι → NavierStokes.SlotColoring.Label}
  {χ : ℕ → D → NavierStokes.LabelSumBounds.WindowPoint} {Y : ℕ → D → NavierStokes.TorusInverse.Plane} {U : Set D}
  {u v : ι → NavierStokes.CorrectionState.Oscillation D},
  NavierStokes.LabelSumBounds.SupportedOscillations sys label χ Y U u →
    NavierStokes.LabelSumBounds.SupportedOscillations sys label χ Y U v →
      ∀ {l k : ι} {n : ℕ},
        1 ≤ (label n l).1 →
          1 ≤ (label n k).1 →
            label n l ≠ label n k → ∀ {x : D}, x ∈ U → ∀ (θ : ℝ) (i j : Fin 3), u l n (x, θ) i * v k n (x, θ) j = 0
